{
  "case_id": "xsu_sg_012_current_specialist_statement",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "not_met",
      "reason": "Svaret rammer 'i særlige tilfælde' og at fremmøde er et udgangspunkt. Det mangler dog de tre konkrete situationer fra vejledningen. Samtidig opstiller det en vag, hjemmelavet tommelfingerregel ('når dokumentationen ikke er tilstrækkelig aktuel eller beskrivende'). Det hævder desuden fejlagtigt, at vejledningens sætning er afkortet, og at betingelsen derfor ikke kan udledes, selv om afsnit 5.1.3.1 er fuldt ud tilgængeligt. Konklusionen svarer ikke til rubrikken."
    },
    "c02_required_elements_complete": {
      "label": "not_met",
      "reason": "Af de fire kritiske elementer er kun det første dækket (mulighed i særlige tilfælde). Tre mangler: journaloplysninger der indikerer funktionstab uden beskrivelse af funktionsniveau og påvirkning, forlængelse af tidsbegrænset tillæg med forældet dokumentation, og påbegyndt behandlingsforløb med begrænsede lægelige oplysninger."
    },
    "c03_direct_relevance": {
      "label": "not_met",
      "reason": "Spørgsmålet er 'hvornår'. Svaret bruger meget plads på fremmøde, uddannelsessøgendes dokumentationspligt og en liste over andre former for lægefaglige oplysninger. Selve 'hvornår' besvares kun generelt og ikke med de konkrete situationer."
    },
    "c04_source_traceability": {
      "label": "met",
      "reason": "Svaret henviser til en identificerbar kilde: Vejledning nr. 10157 af 5. oktober 2026. Det bruger nummererede henvisninger til den, og den er angivet i kildelisten."
    },
    "c05_source_validity": {
      "label": "met",
      "reason": "Vejledning VEJ nr. 10157 af 05/10/2026, afsnit 5.1.3.1, findes i den frosne kildeafgrænsning og er aktuel, autoritativ og anvendelig til spørgsmålet."
    },
    "c06_claim_source_support": {
      "label": "not_met",
      "reason": "Flere påstande støttes ikke af de angivne passager. Svaret hævder, at passagen er afkortet, og at den aktuelle redegørelse er en del af en liste med speciallægeerklæring og udtalelse fra Arbejdsmarkedets Erhvervssikring, uden at det fremgår af afsnit 5.1.3.1. Det hævder også, at dokumentationen skal være nyere end den allerede modtagne. Heller ikke fortolkningen 'typisk ... når der mangler tilstrækkeligt aktuelle oplysninger' er dækket af passagen, som nævner tre specifikke situationer."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "not_met",
      "reason": "Svaret tilføjer krav og regler uden støtte i afsnit 5.1.3.1. Det gælder, at dokumentationen skal være nyere end den allerede modtagne, og at AES-udtalelse og speciallægeerklæring er alternativer. Det gælder også den generelle betingelse, at eksisterende dokumentation ikke er tilstrækkelig aktuel eller beskrivende til at oplyse sagen."
    },
    "c08_qualifications_and_exceptions": {
      "label": "met",
      "reason": "Svaret bevarer 'i særlige tilfælde' og 'som udgangspunkt' for fremmøde, samt lægens mulighed for at udfylde ud fra journalen. Det gør ikke forældet dokumentation til en absolut betingelse."
    },
    "c09_reasoning_coherence": {
      "label": "not_met",
      "reason": "Svaret siger, at den fulde betingelse ikke kan udledes på grund af afkortning. Alligevel drager det en konkret konklusion om 'mest nærliggende', og at redegørelsen 'typisk' bruges ved utilstrækkelig aktualitet. Det er en intern spænding, hvor konklusionen ikke følger af de anførte kilder."
    },
    "c10_legal_modality_precision": {
      "label": "met",
      "reason": "Modaliteten er i det væsentlige præcis: 'kan i særlige tilfælde', 'som udgangspunkt' og lægens 'kan' udfylde på journalen. Svaret gør ikke skøn eller undtagelser absolutte. Formuleringen 'typisk' er en svag tilføjelse, men ændrer ikke modaliteten væsentligt."
    }
  },
  "xhaile_coverage": {
    "A69": {
      "label": "no",
      "reason": "Svaret nævner ikke, at journaloplysninger indikerer funktionstab uden at beskrive funktionsniveau og påvirkning. Det siger kun vagt, at dokumentationen ikke er 'tilstrækkelig aktuel eller beskrivende'."
    },
    "A70": {
      "label": "no",
      "reason": "Forlængelse af et tidsbegrænset handicaptillæg med forældet dokumentation er ikke nævnt."
    },
    "A71": {
      "label": "no",
      "reason": "Påbegyndt behandlingsforløb ved ansøgningstidspunktet med begrænsede lægelige oplysninger er ikke nævnt."
    }
  },
  "overall_notes": "Svaret er kildebaseret og bevarer 'i særlige tilfælde' og 'som udgangspunkt'. Det udelader alle tre konkrete situationer i afsnit 5.1.3.1 og hævder fejlagtigt, at kilden er afkortet. Det tilføjer også uunderstøttede elementer fra andre afsnit og en generel betingelse. Det besvarer derfor ikke 'hvornår' tilstrækkeligt."
}

